			/*
			 * Body에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad(/* cpr.events.CEvent */ e){
				var content = sessionStorage.getItem("print-content");
				if(content){
					document.body.innerHTML = content;
					//인쇄창 열고, 인쇄창이 닫히면 window 닫기.
					window.print();
					window.focus();
			//		document.close();
			//		window.close();
				}
			};
			// End - User Script
			
